code.cpp:
class Solution {
public:
    int findChampion(int n, vector<vector<int>>& edges) {
        vector<int> in_degree(n, 0);
        for (const auto& edge : edges) {
            in_degree[edge[1]]++;
        }

        int champion = -1;
        for (int i = 0; i < n; ++i) {
            if (in_degree[i] == 0) {
                if (champion != -1) {
                    return -1;
                }
                champion = i;
            }
        }

        return champion;
    }
};
